url\":\"/home/12.png\",\"path\":\"static/home/12.png\",\"width\":3136,\"height\":2641,\"thumbUrl\":\"/home/12.png\",\"thumbPath\":\"static/home/12.png\"},\"name\":\"PPI India\",\"risk\":\"none\",\"role\":\"Ketua\",\"slug\":\"ppidk-in\",\"email\":\"selandiabaru@example.com\",\"mapNo\":12,\"phone\":\"+00 000 0000 000\",\"active\":true,\"region\":\"southAsia\",\"socials\":[],\"version\":1,\"website\":null,\"latitude\":21,\"timezone\":\"Asia/Kolkata\",\"createdAt\":\"2026-11-04T13:22:49.532Z\",\"deletedAt\":null,\"instagram\":null,\"longitude\":78,\"updatedAt\":\"2026-11-04T13:22:49.532Z\",\"conditions\":[],\"contactName\":\"Budi Setiawan\",\"countryCode\":\"IN\",\"description\":\"India is a country in South Asia that covers most of the Indian subcontinent. It is the world\'s most populous country and the seventh-largest by area. It borders Pakistan, China, Nepal, Bhutan, Bangladesh and Myanmar, and is bounded by the Arabian Sea, the Bay of Bengal and the Indian Ocean. Its capital is New Delhi.\",\"memberCount\":0,\"contactPublic\":\"\"}','[[\"createdAt\"],[\"updatedAt\"]]'),('dummy-ppi-14','{\"logo\":{\"url\":\"/home/16.png\",\"path\":\"static/home/16.png\",\"width\":555,\"height\":360,\"thumbUrl\":\"/home/16.png\",\"thumbPath\":\"static/home/16.png\"},\"name\":\"PPI Bangladesh\",\"risk\":\"none\",\"role\":\"Ketua\",\"slug\":\"ppidk-bd\",\"email\":\"selandiabaru@example.com\",\"mapNo\":16,\"phone\":\"+00 000 0000 000\",\"active\":true,\"region\":\"southAsia\",\"socials\":[],\"version\":1,\"website\":null,\"latitude\":23.7,\"timezone\":\"Asia/Dhaka\",\"createdAt\":\"2026-11-04T13:22:49.532Z\",\"deletedAt\":null,\"instagram\":null,\"longitude\":90.4,\"updatedAt\":\"2026-11-04T13:22:49.532Z\",\"conditions\":[],\"contactName\":\"Budi Setiawan\",\"countryCode\":\"BD\",\"description\":\"Bangladesh is a country in South Asia at the head of the Bay of Bengal. India surrounds it on almost all sides, and it shares a short border with Myanmar in the southeast. Most of the country sits on the Ganges–Brahmaputra delta, one of the largest river deltas in the world. It is also one of the most densely populated countries on Earth. Its capital is Dhaka.\",\"memberCount\":0,\"contactPublic\":\"\"}','[[\"createdAt\"],[\"updatedAt\"]]'),('dummy-ppi-15','{\"logo\":{\"url\":\"/home/17.png\",\"path\":\"static/home/17.png\",\"width\":739,\"height\":415,\"thumbUrl\":\"/home/17.png\",\"thumbPath\":\"static/home/17.png\"},\"name\":\"PPI Sri Lanka\",\"risk\":\"none\",\"role\":\"Ketua\",\"slug\":\"ppidk-lk\",\"email\":\"selandiabaru@example.com\",\"mapNo\":17,\"phone\":\"+00 000 0000 000\",\"active\":true,\"region\":\"southAsia\",\"socials\":[],\"version\":1,\"website\":null,\"latitude\":7.9,\"timezone\":\"Asia/Colombo\",\"createdAt\":\"2026-11-04T13:22:49.532Z\",\"deletedAt\":null,\"instagram\":null,\"longitude\":80.8,\"updatedAt\":\"2026-11-04T13:22:49.532Z\",\"conditions\":[],\"contactName\":\"Budi Setiawan\",\"countryCode\":\"LK\",\"description\":\"Sri Lanka is an island country in the Indian Ocean, off the southeastern tip of India. The Palk Strait and the Gulf of Mannar separate it from the Indian subcontinent. It is known for its tea, beaches and ancient Buddhist heritage. Its commercial capital is Colombo, and its legislative capital is Sri Jayawardenepura Kotte.\",\"memberCount\":0,\"contactPublic\":\"\"}','[[\"createdAt\"],[\"updatedAt\"]]'),('dummy-ppi-16','{\"logo\":{\"url\":\"/home/13.png\",\"path\":\"static/home/13.png\",\"width\":738,\"height\":416,\"thumbUrl\":\"/home/13.png\",\"thumbPath\":\"static/home/13.png\"},\"name\":\"PPI Kazakhstan\",\"risk\":\"none\",\"role\":\"Ketua\",\"slug\":\"ppidk-kz\",\"email\":\"selandiabaru@example.com\",\"mapNo\":13,\"phone\":\"+00 000 0000 000\",\"active\":true,\"region\":\"middleAsia\",\"socials\":[],\"version\":1,\"website\":null,\"latitude\":48.2,\"timezone\":\"Asia/Almaty\",\"createdAt\":\"2026-11-04T13:22:49.532Z\",\"deletedAt\":null,\"instagram\":null,\"longitude\":67,\"updatedAt\":\"2026-11-04T13:22:49.532Z\",\"conditions\":[],\"contactName\":\"Budi Setiawan\",\"countryCode\":\"KZ\",\"description\":\"Kazakhstan is a country in Central Asia, and a small part of it lies in Eastern Europe west of the Ural River. It is the largest landlocked country in the world and the ninth-largest country overall. It borders Russia, China, Kyrgyzstan, Uzbekistan and Turkmenistan, and has a coastline on the Caspian Sea. Its capital is Astana, and its largest city is Almaty.\",\"memberCount\":0,\"contactPublic\":\"\"}','[[\"createdAt\"],[\"updatedAt\"]]'),('dummy-ppi-17','{\"logo\":{\"url\":\"/home/15.png\",\"path\":\"static/home/15.png\",\"width\":678,\"height\":452,\"thumbUrl\":\"/home/15.png\",\"thumbPath\":\"static/home/15.png\"},\"name\":\"PPI Kirgistan\",\"risk\":\"none\",\"role\":\"Ketua\",\"slug\":\"ppidk-kg\",\"email\":\"selandiabaru@example.com\",\"mapNo\":15,\"phone\":\"+00 000 0000 000\",\"active\":true,\"region\":\"middleAsia\",\"socials\":[],\"version\":1,\"website\":null,\"latitude\":41.2,\"timezone\":\"Asia/Bishkek\",\"createdAt\":\"2026-11-04T13:22:49.532Z\",\"deletedAt\":null,\"instagram\":null,\"longitude\":74.8,\"updatedAt\":\"2026-11-04T13:22:49.532Z\",\"conditions\":[],\"contactName\":\"Budi Setiawan\",\"countryCode\":\"KG\",\"description\":\"Kyrgyzstan is a landlocked, mountainous country in Central Asia, and the Tian Shan range covers most of its territory. It borders Kazakhstan, Uzbekistan, Tajikistan and China. It is known for its alpine scenery and for Issyk-Kul, one of the largest mountain lakes in the world. Its capital and largest city is Bishkek.\",\"memberCount\":0,\"contactPublic\":\"\"}','[[\"createdAt\"],[\"updatedAt\"]]'),('dummy-ppi-np','{\"logo\":null,\"name\":\"PPI Nepal\",\"risk\":\"none\",\"slug\":\"ppidk-np\",\"email\":null,\"mapNo\":18,\"active\":false,\"region\":\"southAsia\",\"socials\":[],\"version\":1,\"website\":null,\"latitude\":28.4,\"timezone\":\"Asia/Kathmandu\",\"createdAt\":\"2026-11-04T12:59:20.111Z\",\"deletedAt\":null,\"instagram\":null,\"longitude\":84.1,\"updatedAt\":\"2026-11-04T13:02:38.315Z\",\"conditions\":[],\"contactName\":\"\",\"countryCode\":\"NP\",\"memberCount\":0,\"contactPublic\":\"\"}','[[\"createdAt\"],[\"updatedAt\"]]');
